const config = $input.first().json;
if (typeof config.api_base_url !== 'string' || !/^https:\/\/[^\s/]+(?:\/[^\s]*)?$/.test(config.api_base_url) || config.api_base_url.includes('.invalid')) throw new Error('Set api_base_url to your reachable HTTPS scanner URL; n8n Cloud cannot reach your localhost.');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuid.test(config.project_id)) throw new Error('Set project_id to a real scanner project UUID.');
if (config.existing_run_id && !uuid.test(config.existing_run_id)) throw new Error('existing_run_id must be empty or a run UUID.');
if (!(config.poll_seconds >= 5 && config.poll_seconds <= 300) || !(config.max_poll_seconds >= config.poll_seconds && config.max_poll_seconds <= 86400)) throw new Error('Choose a 5–300 second poll interval and a bounded polling deadline.');
if (!Number.isInteger(config.review_limit) || config.review_limit < 1 || config.review_limit > 25 || !Number.isInteger(config.review_offset) || config.review_offset < 0) throw new Error('review_limit must be 1–25 and review_offset a nonnegative integer.');
if (typeof config.ai_enabled !== 'boolean') throw new Error('ai_enabled must be a boolean.');
if (typeof config.review_prompt !== 'string' || !config.review_prompt.trim() || config.review_prompt.length > 12000) throw new Error('review_prompt must contain 1–12000 characters.');
return [{ json: config }];

const run = $input.first().json;
if (!run.id || typeof run.status !== 'string') throw new Error('Scanner did not return a run object with id and status.');
const config = $('Configure monitor').first().json;
return [{ json: { run_id: run.id, project_id: config.project_id, deadline_ms: Date.now() + Number(config.max_poll_seconds) * 1000 } }];

const run = $input.first().json;
const initial = $('Initialize polling').first().json;
if (run.id !== initial.run_id || run.project_id !== initial.project_id || !['running', 'completed', 'partial', 'failed', 'cancelled'].includes(run.status)) throw new Error('Unexpected scanner run/project/status response. Check existing_run_id belongs to the configured project.');
const timedOut = run.status === 'running' && Date.now() >= initial.deadline_ms;
return [{ json: { run_id: run.id, status: run.status, keep_waiting: run.status === 'running' && !timedOut, usable: ['completed', 'partial'].includes(run.status), error: run.status === 'cancelled' ? 'The scan was stopped. Previous accepted observations were preserved; this workflow will not send text for AI review.' : timedOut ? 'Polling deadline reached. The scanner continues independently. Set existing_run_id to this run UUID to resume: ' + run.id : run.error || 'Scanner run failed.' } }];

const body = $input.first().json;
const runId = $('Initialize polling').first().json.run_id;
if (body.run_id !== runId || body.images_included !== false || body.text_included !== false || !Array.isArray(body.items)) throw new Error('Expected a metadata-only text manifest for this run.');
const hasMore = body.next_offset !== null && body.next_offset !== undefined;
const items = body.items.filter(pair => ['new', 'changed'].includes(pair.change_status) && pair.current && pair.current.content_status === 'complete' && !(pair.current.analysis && pair.current.analysis.kind === 'text' && pair.current.analysis.content_sha256 === pair.current.content_sha256)).map(pair => ({ ...pair, run_id: runId }));
return [{ json: { run_id: runId, items, has_items: items.length > 0, changed_pairs: items.length, has_more: hasMore, next_offset: hasMore ? body.next_offset : null, pagination_warning: hasMore ? 'More text reviews remain. Reuse this run ID and set review_offset to next_offset; this page is not the complete review.' : null, review_status: 'ready_for_review' } }];

const body = $input.first().json;
const requested = $('Process one text pair').item.json;
if (!Array.isArray(body.items) || body.items.length !== 1 || body.text_included !== true || body.images_included !== false) throw new Error('Expected one text-only evidence pair.');
const pair = body.items[0];
if (body.run_id !== requested.run_id || pair.domain !== requested.domain || pair.scheme !== requested.scheme || !pair.current || pair.current.content_sha256 !== requested.current.content_sha256) throw new Error('Evidence does not match the requested run/domain/scheme/fingerprint.');
if (!['new', 'changed'].includes(pair.change_status) || pair.current.content_status !== 'complete' || typeof pair.current.page_text !== 'string' || !pair.current.page_text.trim() || pair.current.page_text.length > 8000) throw new Error('Evidence must contain complete new or changed text.');
if (pair.current.analysis && pair.current.analysis.kind === 'text' && pair.current.analysis.content_sha256 === pair.current.content_sha256) throw new Error('This text was already reviewed.');
const evidence_json = JSON.stringify(pair);
if (evidence_json.length > 60000 || /"(?:image_data_url|image_url|binary)"\s*:/.test(evidence_json)) throw new Error('Unexpected image data or excessive evidence.');
return [{ json: { run_id: body.run_id, domain: pair.domain, scheme: pair.scheme, change_status: pair.change_status, content_sha256: pair.current.content_sha256, has_previous: Boolean(pair.previous), evidence_json }, pairedItem: { item: 0 } }];

const items = $input.all().map(item => item.json);
const manifest = $('Validate changed manifest').first().json;
const sent = items.reduce((total, item) => total + (item.ai_requests_sent || 0), 0);
const saved = items.reduce((total, item) => total + (item.assessments_saved || 0), 0);
return [{ json: { run_id: manifest.run_id, processed_pairs: items.length, ai_requests_sent: sent, assessments_saved: saved, model: 'gpt-4o-mini', review_status: $('Configure monitor').first().json.ai_enabled ? 'ai_review_page_saved' : 'ai_disabled', has_more: manifest.has_more, next_offset: manifest.next_offset, pagination_warning: manifest.pagination_warning, detail: manifest.has_more ? 'More changed text observations remain; this is one review page, not the complete run.' : 'This page finished. AI results, if enabled, are assessments for human review.' } }];

const response = $input.first().json;
const request = $('Build gpt-4o-mini request').item.json;
if (response.error) throw new Error('OpenAI returned an error; no AI assessment was saved.');
if (typeof response.model !== 'string' || !/^gpt-4o-mini(?:-\d{4}-\d{2}-\d{2})?$/.test(response.model)) throw new Error('Unexpected model in response; no substitution is allowed.');
if (response.status !== 'completed' || !Array.isArray(response.output)) throw new Error('OpenAI response was incomplete or malformed; no assessment was saved.');
const messages = response.output.filter(item => item && item.type === 'message');
if (messages.length !== 1 || response.output.some(item => !item || item.type !== 'message')) throw new Error('Expected exactly one OpenAI message and no tool output.');
const message = messages[0];
if (message.role !== 'assistant' || message.status !== 'completed' || !Array.isArray(message.content) || message.content.length !== 1 || message.content[0].type !== 'output_text') throw new Error('OpenAI response was refused or did not contain one text assessment.');
const assessmentText = message.content[0].text;
let result;
try { result = typeof assessmentText === 'string' ? JSON.parse(assessmentText) : assessmentText; } catch (_) { throw new Error('OpenAI returned invalid JSON; no assessment was saved.'); }
if (!result || Array.isArray(result) || typeof result !== 'object') throw new Error('AI assessment must be a JSON object.');
if (Object.keys(result).sort().join(',') !== 'changed,confidence,risk,summary') throw new Error('Unexpected assessment fields.');
if (typeof result.summary !== 'string' || !result.summary.trim() || result.summary.length > 4000) throw new Error('AI summary must contain 1–4000 characters.');
if (!['low', 'medium', 'high', 'uncertain'].includes(result.risk)) throw new Error('AI risk value is invalid.');
if (result.changed !== null && typeof result.changed !== 'boolean') throw new Error('AI changed value must be boolean or null.');
if (!request.has_previous && result.changed !== null) throw new Error('A first text observation cannot claim a change from an absent baseline.');
if (typeof result.confidence !== 'number' || !Number.isFinite(result.confidence) || result.confidence < 0 || result.confidence > 1) throw new Error('AI confidence must be a finite number from 0 to 1.');
return [{ json: { run_id: request.run_id, domain: request.domain, scheme: request.scheme, change_status: request.change_status, assessment: { domain: request.domain, scheme: request.scheme, content_sha256: request.content_sha256, provider: 'OpenAI', model: 'gpt-4o-mini', summary: result.summary.trim(), risk: result.risk, changed: result.changed, confidence: result.confidence } } }];
